                                    {requiresLogin && (
                                        <span style={{
                                            background: 'rgba(239,68,68,0.15)',
                                            color: '#ef4444',
                                            padding: '2px 12px',
                                            borderRadius: '12px',
                                            fontSize: 'var(--text-sm)',
                                            fontWeight: 600,
                                            marginBottom: '0.75rem',
                                        }}>
                                            {L(LABELS.loginRequired)}
