                                        marginTop: '0.5rem',
                                        flex: 1,
                                        position: 'relative',
                                    }}>
                                        {TIER_DESCRIPTIONS[tierId]?.[loc] || ''}
                                    </p>

                                    <button style={{
                                        marginTop: '1.5rem',
                                        padding: '0.75rem 2rem',
                                        borderRadius: 'var(--radius-lg)',
                                        border: 'none',
                                        background: `linear-gradient(135deg, ${color}, ${color}cc)`,
                                        color: '#fff',
                                        fontWeight: 700,
                                        cursor: 'pointer',
                                        transition: 'opacity 0.2s',
                                        width: '100%',
                                        position: 'relative',
                                    }}
                                        onMouseEnter={(e) => { e.currentTarget.style.opacity = '0.85'; }}
                                        onMouseLeave={(e) => { e.currentTarget.style.opacity = '1'; }}
                                    >
                                        {L(LABELS.select)}
                                    </button>
                                </div>
                            );
                        })}
                    </div>

                    <p style={{
                        textAlign: 'center',
                        marginTop: '2rem',
                        color: 'var(--color-accent-primary)',
                        fontSize: 'var(--text-sm)',
                    }}>
                        {L(LABELS.freeTrial)}
                    </p>
                </div>
            </section>

            {/* Login Required Modal */}
            {showLoginModal && (
                <div style={{
                    position: 'fixed',
                    inset: 0,
                    background: 'rgba(0,0,0,0.7)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    zIndex: 1000,
                    backdropFilter: 'blur(4px)',
                }} onClick={() => setShowLoginModal(false)}>
                    <div style={{
                        background: 'var(--color-surface)',
                        borderRadius: 'var(--radius-xl)',
                        padding: '2.5rem',
                        maxWidth: '420px',
                        width: '90%',
                        textAlign: 'center',
                        border: '1px solid var(--color-border)',
                    }} onClick={(e) => e.stopPropagation()}>
                        <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🔒</div>
                        <h3 style={{ fontWeight: 700, fontSize: 'var(--text-xl)', marginBottom: '0.5rem' }}>
                            {TIER_NAMES[selectedForLogin]?.[loc] || ''}
                        </h3>
                        <p style={{ color: 'var(--color-text-secondary)', marginBottom: '1.5rem', lineHeight: 1.6 }}>
                            {loc === 'ko' ? 'Pro/Archmage 등급은 로그인이 필요합니다.\n가입하면 +2 무료 크레딧을 받을 수 있습니다!' :
                                loc === 'ja' ? 'Pro/Archmageグレードにはログインが必要です。\n登録すると+2無料クレジットがもらえます！' :
                                    loc === 'zh' ? 'Pro/Archmage等级需要登录。\n注册可获得+2免费积分！' :
                                        'Pro/Archmage grades require login.\nSign up to get +2 free credits!'}
                        </p>
                        <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'center' }}>
                            <button
                                onClick={() => router.push(`/${loc}/account`)}
                                style={{
                                    padding: '0.75rem 1.5rem',
                                    borderRadius: 'var(--radius-lg)',
                                    border: 'none',
                                    background: 'var(--color-accent-primary)',
                                    color: '#fff',
                                    fontWeight: 700,
                                    cursor: 'pointer',
                                }}
                            >
                                {loc === 'ko' ? '로그인 / 가입' : loc === 'ja' ? 'ログイン/登録' : loc === 'zh' ? '登录/注册' : 'Login / Sign Up'}
                            </button>
                            <button
                                onClick={() => setShowLoginModal(false)}
                                style={{
                                    padding: '0.75rem 1.5rem',
                                    borderRadius: 'var(--radius-lg)',
                                    border: '1px solid var(--color-border)',
                                    background: 'transparent',
                                    color: 'var(--color-text-secondary)',
                                    fontWeight: 600,
                                    cursor: 'pointer',
                                }}
                            >
                                {loc === 'ko' ? '닫기' : loc === 'ja' ? '閉じる' : loc === 'zh' ? '关闭' : 'Close'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <style>{`
                @keyframes float {
                    0%, 100% { transform: translateY(0); }
                    50% { transform: translateY(-4px); }
                }
            `}</style>
        </>
    );
}

