'use client';

import { useParams, useRouter } from 'next/navigation';
import { useState, useEffect, useCallback } from 'react';
import { getClientAuth } from '@/lib/firebase/client';
import { onAuthStateChanged, User } from 'firebase/auth';

type Tab = 'profile' | 'history' | 'subscription' | 'payments';

interface Profile {
    birthDate?: string;
    birthTime?: string;
    birthPlace?: string;
    lat?: number;
    lng?: number;
}

interface ReadingRecord {
    id: string;
    module: string;
    question?: string;
    summary?: string;
    createdAt: string;
}

export default function MypagePage() {
    const { locale } = useParams();
    const router = useRouter();
    const loc = (locale as string) || 'ko';
    const [user, setUser] = useState<User | null>(null);
    const [activeTab, setActiveTab] = useState<Tab>('profile');
    const [loading, setLoading] = useState(true);

    // 데모 프로필 데이터
    const [profile] = useState<Profile>({});
    const [readings] = useState<ReadingRecord[]>([]);

    const labels: Record<string, Record<string, string>> = {
        title: { ko: '마이페이지', ja: 'マイページ', en: 'My Page', zh: '我的页面' },
        tabProfile: { ko: '내 프로필', ja: 'プロフィール', en: 'My Profile', zh: '我的资料' },
        tabHistory: { ko: '질문 기록', ja: '質問履歴', en: 'History', zh: '提问记录' },
        tabSubscription: { ko: '구독 상태', ja: 'サブスクリプション', en: 'Subscription', zh: '订阅状态' },
        tabPayments: { ko: '결제 내역', ja: '決済履歴', en: 'Payments', zh: '支付记录' },
        needLogin: { ko: '로그인이 필요합니다', ja: 'ログインが必要です', en: 'Login required', zh: '需要登录' },
        goLogin: { ko: '로그인 하러 가기', ja: 'ログインする', en: 'Go to Login', zh: '去登录' },
        noBirthData: { ko: '출생 정보가 아직 입력되지 않았습니다', ja: '出生情報がまだ入力されていません', en: 'Birth data not yet entered', zh: '尚未输入出生信息' },
        enterBirthData: { ko: '사주 분석에서 입력', ja: '四柱分析で入力', en: 'Enter via Saju analysis', zh: '通过四柱分析输入' },
        birthDate: { ko: '생년월일', ja: '生年月日', en: 'Date of Birth', zh: '出生日期' },
        birthTime: { ko: '출생 시간', ja: '出生時刻', en: 'Time of Birth', zh: '出生时间' },
        birthPlace: { ko: '출생 장소', ja: '出生地', en: 'Place of Birth', zh: '出生地' },
        noHistory: { ko: '아직 질문 기록이 없습니다', ja: 'まだ質問履歴がありません', en: 'No history yet', zh: '暂无提问记录' },
        startReading: { ko: '지금 운세 보러 가기', ja: '今すぐ占いを見る', en: 'Start a reading', zh: '现在去看运势' },
        currentTier: { ko: '현재 등급', ja: '現在のランク', en: 'Current Tier', zh: '当前等级' },
        dailyUsage: { ko: '오늘 사용량', ja: '今日の使用量', en: 'Daily Usage', zh: '今日用量' },
        dailyLimit: { ko: '일일 한도', ja: '日次リミット', en: 'Daily Limit', zh: '每日限额' },
        renewalDate: { ko: '갱신 예정일', ja: '更新予定日', en: 'Renewal Date', zh: '续费日期' },
        free: { ko: '무료 (견습 점술사)', ja: '無料（見習い占い師）', en: 'Free (Apprentice Seer)', zh: '免费（学徒占卜师）' },
        upgradeCta: { ko: '등급 업그레이드', ja: 'ランクアップ', en: 'Upgrade', zh: '升级' },
        noPayments: { ko: '결제 내역이 없습니다', ja: '決済履歴はありません', en: 'No payments', zh: '暂无支付记录' },
    };

    const checkAuth = useCallback(() => {
        const auth = getClientAuth();
        if (!auth) {
            setLoading(false);
            return;
        }
        const unsub = onAuthStateChanged(auth, (u) => {
            setUser(u);
            setLoading(false);
        });
        return unsub;
    }, []);

    useEffect(() => {
        const unsub = checkAuth();
        return () => { if (unsub) unsub(); };
    }, [checkAuth]);

    if (loading) {
        return (
            <section className="section">
                <div className="container" style={{ maxWidth: '800px', textAlign: 'center', padding: '80px 0' }}>
                    <div style={{ fontSize: '2rem', animation: 'spin 1s linear infinite' }}>⏳</div>
                </div>
            </section>
        );
    }

    if (!user) {
        return (
            <section className="section">
                <div className="container" style={{ maxWidth: '500px', textAlign: 'center' }}>
                    <div className="glass-card" style={{ padding: '48px 32px' }}>
                        <div style={{ fontSize: '3rem', marginBottom: '16px' }}>🔒</div>
                        <h2 style={{ fontSize: 'var(--text-2xl)', fontWeight: 700, marginBottom: '12px' }}>
                            {labels.needLogin[loc]}
                        </h2>
                        <a href={`/${loc}/account`} className="btn btn-primary" style={{ marginTop: '16px' }}>
                            {labels.goLogin[loc]}
                        </a>
                    </div>
                </div>
            </section>
        );
    }

    const tabs: { key: Tab; label: string; icon: string }[] = [
        { key: 'profile', label: labels.tabProfile[loc], icon: '👤' },
        { key: 'history', label: labels.tabHistory[loc], icon: '📜' },
        { key: 'subscription', label: labels.tabSubscription[loc], icon: '⭐' },
        { key: 'payments', label: labels.tabPayments[loc], icon: '💳' },
    ];

    return (
        <section className="section">
            <div className="container" style={{ maxWidth: '900px' }}>
                {/* 헤더 */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: 'var(--space-8)' }}>
                    <div style={{
                        width: '56px',
                        height: '56px',
                        borderRadius: '50%',
                        background: 'linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-gold))',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '24px',
                        fontWeight: 800,
                        color: '#fff',
                    }}>
                        {(user.displayName || user.email || '?')[0].toUpperCase()}
                    </div>
                    <div>
                        <h1 style={{ fontSize: 'var(--text-2xl)', fontWeight: 800 }}>
                            {labels.title[loc]}
                        </h1>
                        <p style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>
                            {user.email}
                        </p>
                    </div>
                </div>

                {/* 탭 바 */}
                <div style={{
                    display: 'flex',
                    gap: '4px',
                    background: 'rgba(255,255,255,0.03)',
                    borderRadius: '14px',
                    padding: '4px',
                    marginBottom: 'var(--space-6)',
                    overflowX: 'auto',
                }}>
                    {tabs.map((tab) => (
                        <button
                            key={tab.key}
                            onClick={() => setActiveTab(tab.key)}
                            style={{
                                flex: 1,
                                padding: '12px 16px',
                                borderRadius: '10px',
                                border: 'none',
                                background: activeTab === tab.key ? 'var(--color-accent-primary)' : 'transparent',
                                color: activeTab === tab.key ? '#fff' : 'var(--color-text-secondary)',
                                fontWeight: 600,
                                fontSize: 'var(--text-sm)',
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                                whiteSpace: 'nowrap',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                gap: '6px',
                            }}
                        >
                            <span>{tab.icon}</span>
                            <span>{tab.label}</span>
                        </button>
                    ))}
                </div>

                {/* 탭 콘텐츠 */}
                <div className="glass-card" style={{ padding: 'var(--space-8)', minHeight: '300px' }}>
                    {activeTab === 'profile' && (
                        <div>
                            {profile.birthDate ? (
                                <div style={{ display: 'grid', gap: '16px' }}>
                                    <InfoRow label={labels.birthDate[loc]} value={profile.birthDate} />
                                    <InfoRow label={labels.birthTime[loc]} value={profile.birthTime || '-'} />
                                    <InfoRow label={labels.birthPlace[loc]} value={profile.birthPlace || '-'} />
                                </div>
                            ) : (
                                <EmptyState
                                    emoji="📝"
                                    message={labels.noBirthData[loc]}
                                    actionLabel={labels.enterBirthData[loc]}
                                    actionHref={`/${loc}/saju`}
                                />
                            )}
                        </div>
                    )}

                    {activeTab === 'history' && (
                        <div>
                            {readings.length > 0 ? (
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                                    {readings.map((r) => (
                                        <div key={r.id} className="glass-card" style={{ padding: '16px' }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                                                <span style={{ fontSize: 'var(--text-sm)', fontWeight: 600, color: 'var(--color-accent-primary)' }}>
                                                    {r.module}
                                                </span>
                                                <span style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)' }}>
                                                    {r.createdAt}
                                                </span>
                                            </div>
                                            {r.question && <p style={{ fontSize: 'var(--text-sm)' }}>{r.question}</p>}
                                            {r.summary && <p style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-secondary)', marginTop: '4px' }}>{r.summary}</p>}
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <EmptyState
                                    emoji="🔮"
                                    message={labels.noHistory[loc]}
                                    actionLabel={labels.startReading[loc]}
                                    actionHref={`/${loc}/saju`}
                                />
                            )}
                        </div>
                    )}

                    {activeTab === 'subscription' && (
                        <div style={{ display: 'grid', gap: '16px' }}>
                            <InfoRow label={labels.currentTier[loc]} value={labels.free[loc]} accent />
                            <InfoRow label={labels.dailyUsage[loc]} value="0 / 5" />
                            <InfoRow label={labels.dailyLimit[loc]} value={`5 ${loc === 'ko' ? '질문' : 'questions'}`} />
                            <InfoRow label={labels.renewalDate[loc]} value="-" />
                            <div style={{ marginTop: '16px', textAlign: 'center' }}>
                                <a href={`/${loc}/pricing`} className="btn btn-gold">
                                    ⬆ {labels.upgradeCta[loc]}
                                </a>
                            </div>
                        </div>
                    )}

                    {activeTab === 'payments' && (
                        <EmptyState
                            emoji="💳"
                            message={labels.noPayments[loc]}
                            actionLabel={labels.upgradeCta[loc]}
                            actionHref={`/${loc}/pricing`}
                        />
                    )}
                </div>
            </div>
        </section>
    );
}

/** 정보 행 */
function InfoRow({ label, value, accent }: { label: string; value: string; accent?: boolean }) {
    return (
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 0', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
            <span style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-secondary)' }}>{label}</span>
            <span style={{
                fontSize: 'var(--text-sm)',
                fontWeight: 600,
                color: accent ? 'var(--color-accent-primary)' : 'var(--color-text-primary)',
            }}>
                {value}
            </span>
        </div>
    );
}

/** 빈 상태 */
function EmptyState({ emoji, message, actionLabel, actionHref }: { emoji: string; message: string; actionLabel: string; actionHref: string }) {
    return (
        <div style={{ textAlign: 'center', padding: '40px 0' }}>
            <div style={{ fontSize: '3rem', marginBottom: '16px', opacity: 0.3 }}>{emoji}</div>
            <p style={{ color: 'var(--color-text-muted)', marginBottom: '20px' }}>{message}</p>
            <a href={actionHref} className="btn btn-primary btn-sm">
                {actionLabel}
            </a>
        </div>
    );
}

'use client';

import { useTranslations } from 'next-intl';
import { useParams } from 'next/navigation';
import { useState, useEffect } from 'react';
import TierStatsPanel from '@/components/tiers/TierStatsPanel';
import { TIER_ORDER, TIER_NAMES, TIER_COLORS, TIER_AURA } from '@/lib/tiers';

interface TierDef {
    id: string;
    questions: string;
    features: string[];
    priceKRW?: { regular: number; launch: number; renewal: number };
    priceUSD?: { regular: number; launch: number; renewal: number };
    priceJPY?: { regular: number; launch: number; renewal: number };
}

const TIERS: TierDef[] = [
    { id: 'free', questions: '5/day', features: ['basic'] },
    { id: 'plus', questions: '30/day', priceKRW: { regular: 30000, launch: 4900, renewal: 19000 }, priceUSD: { regular: 23, launch: 3.5, renewal: 14 }, priceJPY: { regular: 3000, launch: 500, renewal: 1900 }, features: ['medium', 'noAds'] },
    { id: 'pro', questions: '100/day', priceKRW: { regular: 300000, launch: 10000, renewal: 59000 }, priceUSD: { regular: 230, launch: 7.5, renewal: 45 }, priceJPY: { regular: 30000, launch: 1000, renewal: 5900 }, features: ['deep', 'noAds', 'crossModule'] },
    { id: 'archmage', questions: 'Unlimited', priceKRW: { regular: 990000, launch: 49000, renewal: 199000 }, priceUSD: { regular: 750, launch: 37, renewal: 150 }, priceJPY: { regular: 99000, launch: 4900, renewal: 19900 }, features: ['dualPass', 'noAds', 'crossModule', 'annualForecast'] },
];

// 각 티어의 캐릭터 이미지 매핑
const TIER_IMAGES: Record<string, Record<'male' | 'female', string>> = {
    free: { male: '/images/tiers/Apprentice_male.png', female: '/images/tiers/Apprentice_female.png' },
    plus: { male: '/images/tiers/seer_male.png', female: '/images/tiers/seer_female.png' },
    pro: { male: '/images/tiers/Grand_Seer_male.png', female: '/images/tiers/Grand_Seer_female.png' },
    archmage: { male: '/images/tiers/archmage_male.png', female: '/images/tiers/archmage_female.png' },
};

const TIER_AURA_SIZES: Record<string, string> = {
    free: '160px',
    plus: '200px',
    pro: '240px',
    archmage: '280px',
};

function formatPrice(amount: number, locale: string): string {
    const currency = locale === 'ko' ? 'KRW' : locale === 'ja' ? 'JPY' : 'USD';
    return new Intl.NumberFormat(
        locale === 'ko' ? 'ko-KR' : locale === 'ja' ? 'ja-JP' : 'en-US',
        { style: 'currency', currency, maximumFractionDigits: 0 }
    ).format(amount);
}

export default function PricingPage() {
    const t = useTranslations();
    const { locale } = useParams();
    const loc = (locale as string) || 'ko';
    const [selectedTierIndex, setSelectedTierIndex] = useState(0);
    const [gender, setGender] = useState<'male' | 'female'>('female');
    const [paymentsEnabled, setPaymentsEnabled] = useState(false);
    const selectedTier = TIERS[selectedTierIndex];
    const tierId = selectedTier.id;
    const color = TIER_COLORS[tierId];
    const aura = TIER_AURA[tierId];

    useEffect(() => {
        fetch('/api/config').then(r => r.json()).then(d => setPaymentsEnabled(d.paymentsEnabled)).catch(() => { });
    }, []);

    function getPrice(tier: TierDef, type: 'launch' | 'renewal' | 'regular'): string {
        if (tier.id === 'free') return t('tiers.free');
        const priceSet = loc === 'ko' ? tier.priceKRW : loc === 'ja' ? tier.priceJPY : tier.priceUSD;
        if (!priceSet) return '';
        return formatPrice(priceSet[type], loc);
    }

    const featLabels: Record<string, Record<string, string>> = {
        basic: { ko: '기본 운세 분석', ja: '基本占い', en: 'Basic readings', zh: '基础分析' },
        medium: { ko: '중간 깊이 분석', ja: '中程度分析', en: 'Medium-depth analysis', zh: '中等深度分析' },
        deep: { ko: '심층 분석', ja: '深層分析', en: 'Deep analysis', zh: '深度分析' },
        noAds: { ko: '광고 없음', ja: '広告なし', en: 'No ads', zh: '无广告' },
        crossModule: { ko: '크로스모듈 분석', ja: 'クロスモジュール', en: 'Cross-module', zh: '交叉分析' },
        dualPass: { ko: '이중 추론 분석', ja: '二重推論', en: 'Dual reasoning', zh: '双重推理' },
        annualForecast: { ko: '연간 예측', ja: '年間予測', en: 'Annual forecast', zh: '年度预测' },
    };

    const genderLabels: Record<string, Record<string, string>> = {
        male: { ko: '남성', ja: '男性', en: 'Male', zh: '男性' },
        female: { ko: '여성', ja: '女性', en: 'Female', zh: '女性' },
    };

    return (
        <section className="section">
            <div className="container" style={{ maxWidth: '1100px' }}>
                {/* 헤더 */}
                <div className="text-center" style={{ marginBottom: 'var(--space-10)' }}>
                    <h1 style={{ fontSize: 'var(--text-4xl)', fontWeight: 800, marginBottom: 'var(--space-3)' }}>
                        <span className="text-gradient">{t('pricing.title')}</span>
                    </h1>
                    <p style={{ color: 'var(--color-text-secondary)', fontSize: 'var(--text-lg)' }}>
                        {t('pricing.subtitle')}
                    </p>
                </div>

                {/* 성별 토글 */}
                <div style={{ display: 'flex', justifyContent: 'center', gap: '8px', marginBottom: '24px' }}>
                    {(['male', 'female'] as const).map((g) => (
                        <button
                            key={g}
                            onClick={() => setGender(g)}
                            style={{
                                padding: '8px 20px',
                                borderRadius: '20px',
                                background: gender === g
                                    ? `linear-gradient(135deg, ${color}40, ${color}20)`
                                    : 'rgba(255,255,255,0.03)',
                                border: gender === g ? `1px solid ${color}` : '1px solid rgba(255,255,255,0.1)',
                                color: gender === g ? '#fff' : 'rgba(255,255,255,0.5)',
                                cursor: 'pointer',
                                fontSize: '13px',
                                fontWeight: 600,
                                transition: 'all 0.3s ease',
                            }}
                        >
                            {g === 'male' ? '🧙‍♂️' : '🧙‍♀️'} {genderLabels[g][loc] || genderLabels[g].en}
                        </button>
                    ))}
                </div>

                {/* RPG 캐릭터 선택 레이아웃 */}
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 340px', gap: 'var(--space-8)', alignItems: 'start' }}>
                    {/* LEFT — 캐릭터 스테이지 */}
                    <div>
                        {/* 캐릭터 디스플레이 */}
                        <div style={{
                            position: 'relative',
                            height: '420px',
                            borderRadius: '20px',
                            overflow: 'hidden',
                            background: 'linear-gradient(180deg, rgba(15,10,30,0.9) 0%, rgba(20,15,40,0.95) 100%)',
                            border: `1px solid ${color}30`,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                        }}>
                            {/* 오라 배경 */}
                            <div style={{
                                position: 'absolute',
                                width: TIER_AURA_SIZES[tierId],
                                height: TIER_AURA_SIZES[tierId],
                                borderRadius: '50%',
                                background: `radial-gradient(circle, ${aura}, transparent)`,
                                animation: 'auraPulse 3s ease-in-out infinite',
                            }} />

                            {/* 마법진 */}
                            <div style={{
                                position: 'absolute',
                                bottom: '30px',
                                width: '240px',
                                height: '60px',
                                borderRadius: '50%',
                                background: `radial-gradient(ellipse, ${color}25, transparent 70%)`,
                                border: `1px solid ${color}20`,
                            }} />

                            {/* 캐릭터 이미지 */}
                            <div style={{
                                position: 'relative',
                                zIndex: 2,
                                textAlign: 'center',
                                animation: 'characterFloat 4s ease-in-out infinite',
                            }}>
                                <img
                                    src={TIER_IMAGES[tierId][gender]}
                                    alt={TIER_NAMES[tierId]?.[loc] || tierId}
                                    style={{
                                        height: '300px',
                                        objectFit: 'contain',
                                        filter: `drop-shadow(0 0 30px ${color}60)`,
                                        transition: 'all 0.5s cubic-bezier(0.22, 1, 0.36, 1)',
                                    }}
                                />
                            </div>

                            {/* 티어 이름 오버레이 */}
                            <div style={{
                                position: 'absolute',
                                top: '20px',
                                left: '20px',
                            }}>
                                <span style={{
                                    fontSize: '11px',
                                    fontWeight: 700,
                                    color: color,
                                    textTransform: 'uppercase',
                                    letterSpacing: '0.15em',
                                }}>
                                    {tierId}
                                </span>
                                <h2 style={{ fontSize: '24px', fontWeight: 800, color: '#fff', margin: '4px 0' }}>
                                    {TIER_NAMES[tierId]?.[loc] || tierId}
                                </h2>
                            </div>

                            {/* 성별 표시 배지 */}
                            <div style={{
                                position: 'absolute',
                                top: '20px',
                                right: '20px',
                                fontSize: '20px',
                                background: 'rgba(0,0,0,0.4)',
                                borderRadius: '50%',
                                width: '36px',
                                height: '36px',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                border: '1px solid rgba(255,255,255,0.1)',
                            }}>
                                {gender === 'male' ? '♂' : '♀'}
                            </div>
                        </div>

                        {/* 캐릭터 선택 바 */}
                        <div style={{
                            display: 'flex',
                            gap: '12px',
                            justifyContent: 'center',
                            marginTop: '16px',
                        }}>
                            {TIER_ORDER.map((tid, i) => (
                                <button
                                    key={tid}
                                    onClick={() => setSelectedTierIndex(i)}
                                    style={{
                                        width: selectedTierIndex === i ? '80px' : '64px',
                                        height: selectedTierIndex === i ? '80px' : '64px',
                                        borderRadius: '14px',
                                        background: selectedTierIndex === i
                                            ? `linear-gradient(135deg, ${TIER_COLORS[tid]}30, ${TIER_COLORS[tid]}10)`
                                            : 'rgba(255,255,255,0.03)',
                                        border: selectedTierIndex === i
                                            ? `2px solid ${TIER_COLORS[tid]}`
                                            : '1px solid rgba(255,255,255,0.1)',
                                        display: 'flex',
                                        flexDirection: 'column',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        cursor: 'pointer',
                                        transition: 'all 0.3s ease',
                                        transform: selectedTierIndex === i ? 'translateY(-4px)' : 'none',
                                        padding: '4px',
                                        overflow: 'hidden',
                                    }}
                                >
                                    <img
                                        src={TIER_IMAGES[tid][gender]}
                                        alt={tid}
                                        style={{
                                            height: selectedTierIndex === i ? '50px' : '38px',
                                            objectFit: 'contain',
                                            transition: 'height 0.3s',
                                            filter: selectedTierIndex === i
                                                ? `drop-shadow(0 0 6px ${TIER_COLORS[tid]}80)`
                                                : 'brightness(0.6)',
                                        }}
                                    />
                                    <span style={{
                                        fontSize: '9px',
                                        color: selectedTierIndex === i ? TIER_COLORS[tid] : 'rgba(255,255,255,0.4)',
                                        fontWeight: 700,
                                        marginTop: '2px',
                                    }}>
                                        {TIER_NAMES[tid]?.[loc]?.split(' ')[0] || tid}
                                    </span>
                                </button>
                            ))}
                        </div>

                        {/* 가격 + CTA */}
                        <div className="glass-card" style={{ marginTop: '16px', padding: '24px', textAlign: 'center' }}>
                            {tierId === 'free' ? (
                                <>
                                    <span style={{ fontSize: 'var(--text-3xl)', fontWeight: 800 }}>{t('tiers.free')}</span>
                                    <p style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)', marginTop: '4px' }}>
                                        {selectedTier.questions} {loc === 'ko' ? '질문' : 'questions'}
                                    </p>
                                    <button className="btn btn-secondary" style={{ width: '100%', marginTop: '16px' }}>
                                        {t('tiers.currentPlan')}
                                    </button>
                                </>
                            ) : (
                                <>
                                    <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'center', gap: '8px' }}>
                                        <span style={{ fontSize: '11px', color, fontWeight: 600, textTransform: 'uppercase' }}>
                                            {t('tiers.launchSpecial')}
                                        </span>
                                    </div>
                                    <span style={{ fontSize: 'var(--text-4xl)', fontWeight: 800 }}>
                                        {getPrice(selectedTier, 'launch')}
                                    </span>
                                    <span style={{ fontSize: 'var(--text-sm)', color: 'var(--color-text-muted)' }}>
                                        {t('tiers.perYear')}
                                    </span>
                                    <div style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', marginTop: '8px' }}>
                                        <s>{t('tiers.regularPrice')}: {getPrice(selectedTier, 'regular')}</s>
                                        {' · '}
                                        {t('tiers.renewalPrice')}: {getPrice(selectedTier, 'renewal')}{t('tiers.perYear')}
                                    </div>
                                    <div style={{ display: 'flex', gap: '8px', marginTop: '8px', justifyContent: 'center', flexWrap: 'wrap' }}>
                                        <span style={{ fontSize: '12px', color: 'rgba(255,255,255,0.5)' }}>
                                            ✦ {selectedTier.questions} {loc === 'ko' ? '질문' : 'questions'}
                                        </span>
                                        {selectedTier.features.map((f) => (
                                            <span key={f} style={{ fontSize: '12px', color: 'rgba(255,255,255,0.5)' }}>
                                                ✦ {featLabels[f]?.[loc] || f}
                                            </span>
                                        ))}
                                    </div>
                                    {paymentsEnabled ? (
                                        <a
                                            href={`/${loc}/checkout/toss?tier=${tierId}`}
                                            className={`btn ${tierId === 'archmage' ? 'btn-gold' : 'btn-primary'}`}
                                            style={{ width: '100%', marginTop: '16px' }}
                                        >
                                            {t('tiers.subscribe')}
                                        </a>
                                    ) : (
                                        <button
                                            disabled
                                            className="btn btn-secondary"
                                            style={{ width: '100%', marginTop: '16px', opacity: 0.6, cursor: 'not-allowed' }}
                                        >
                                            ✨ {loc === 'ko' ? '준비 중' : loc === 'ja' ? '準備中' : loc === 'zh' ? '准备中' : 'Coming Soon'}
                                        </button>
                                    )}
                                </>
                            )}
                        </div>
                    </div>

                    {/* RIGHT — 스탯 패널 */}
                    <div>
                        <TierStatsPanel tierId={tierId} locale={loc} />
                    </div>
                </div>
            </div>

            <style>{`
                @keyframes auraPulse {
                    0%, 100% { transform: scale(1); opacity: 0.6; }
                    50% { transform: scale(1.15); opacity: 1; }
                }
                @keyframes characterFloat {
                    0%, 100% { transform: translateY(0); }
                    50% { transform: translateY(-8px); }
                }
                @media (max-width: 768px) {
                    .container > div:last-child {
                        grid-template-columns: 1fr !important;
                    }
                }
            `}</style>
        </section>
    );
}

'use client';

import { useParams } from 'next/navigation';
import { useState, useMemo } from 'react';
import { useInterpret } from '@/lib/hooks/useInterpret';
import FortuneResultPanel from '@/components/fortune/FortuneResultPanel';
import { calculateSaju } from '@/lib/saju/calculator';

export default function SajuPage() {
    const { locale } = useParams();
    const loc = (locale as string) || 'ko';

    const [birthDate, setBirthDate] = useState('');
    const [birthTime, setBirthTime] = useState('');
    const [isLunar, setIsLunar] = useState(false);
    const [gender, setGender] = useState<'male' | 'female'>('female');
    const [question, setQuestion] = useState('');
    const [showChart, setShowChart] = useState(false);
    const { result, loading, error, errorCode, interpret, reset } = useInterpret();

    // 출생 정보 입력 시 실시간 사주 계산
    const sajuResult = useMemo(() => {
        return calculateSaju(birthDate, birthTime || undefined);
    }, [birthDate, birthTime]);

    const labels: Record<string, Record<string, string>> = {
        title: { ko: '사주팔자 분석', ja: '四柱推命分析', en: 'Four Pillars of Destiny', zh: '四柱八字分析' },
        subtitle: { ko: '사주명리학 기반 정밀 분석 — 절기 기준 월주 결정', ja: '四柱推命学に基づく精密分析', en: 'Traditional Saju analysis with solar-term boundaries', zh: '基于四柱命理学的精确分析' },
        date: { ko: '생년월일', ja: '生年月日', en: 'Date of Birth', zh: '出生日期' },
        time: { ko: '출생 시간', ja: '出生時刻', en: 'Time of Birth', zh: '出生时间' },
        lunar: { ko: '음력으로 입력', ja: '旧暦で入力', en: 'Enter in Lunar Calendar', zh: '农历输入' },
        analyze: { ko: '✦ AI 분석하기', ja: '✦ AI分析する', en: '✦ AI Analyze', zh: '✦ AI分析' },
        question: { ko: '궁금한 점 (선택)', ja: '質問（任意）', en: 'Your Question (optional)', zh: '您的问题（可选）' },
        questionPlaceholder: { ko: '올해의 운세가 궁금합니다...', ja: '今年の運勢が気になります...', en: "I'm curious about this year's fortune...", zh: '想知道今年的运势...' },
        genderLabel: { ko: '성별', ja: '性別', en: 'Gender', zh: '性别' },
        male: { ko: '남성', ja: '男性', en: 'Male', zh: '男性' },
        female: { ko: '여성', ja: '女性', en: 'Female', zh: '女性' },
        enterInfo: { ko: '출생 정보를 입력하면 사주팔자가 표시됩니다', ja: '出生情報を入力すると四柱八字が表示されます', en: 'Enter birth data to reveal your Four Pillars', zh: '输入出生信息以显示四柱八字' },
    };

    const pillarLabels: Record<string, Record<string, string>> = {
        year: { ko: '년주', ja: '年柱', en: 'Year', zh: '年柱' },
        month: { ko: '월주', ja: '月柱', en: 'Month', zh: '月柱' },
        day: { ko: '일주', ja: '日柱', en: 'Day', zh: '日柱' },
        hour: { ko: '시주', ja: '時柱', en: 'Hour', zh: '時柱' },
        stem: { ko: '천간', ja: '天干', en: 'Stem', zh: '天干' },
        branch: { ko: '지지', ja: '地支', en: 'Branch', zh: '地支' },
    };

    const handleAnalyze = () => {
        if (!birthDate) return;
        setShowChart(true);
        interpret({
            system: 'saju',
            locale: loc,
            question: question || (loc === 'ko' ? '전반적인 사주 분석을 해주세요' : 'Please provide a general Saju analysis'),
            birthDate,
            birthTime: birthTime || undefined,
            isLunar,
            gender,
        });
    };

    const pillarsOrder = ['hour', 'day', 'month', 'year'] as const;
    const elementsList = [
        { key: 'wood' as const, name: { ko: '목(木)', ja: '木', en: 'Wood', zh: '木' }, color: '#22c55e', icon: '🌳' },
        { key: 'fire' as const, name: { ko: '화(火)', ja: '火', en: 'Fire', zh: '火' }, color: '#ef4444', icon: '🔥' },
        { key: 'earth' as const, name: { ko: '토(土)', ja: '土', en: 'Earth', zh: '土' }, color: '#eab308', icon: '⛰️' },
        { key: 'metal' as const, name: { ko: '금(金)', ja: '金', en: 'Metal', zh: '金' }, color: '#94a3b8', icon: '⚔️' },
        { key: 'water' as const, name: { ko: '수(水)', ja: '水', en: 'Water', zh: '水' }, color: '#3b82f6', icon: '💧' },
    ];

    // 전체 8개 중 비율 계산
    const maxEl = sajuResult ? Math.max(...Object.values(sajuResult.elements), 1) : 1;

    return (
        <section className="section">
            <div className="container" style={{ maxWidth: '800px' }}>
                <div className="text-center" style={{ marginBottom: 'var(--space-10)' }}>
                    <h1 style={{ fontSize: 'var(--text-4xl)', fontWeight: 800, marginBottom: 'var(--space-3)' }}>
                        <span className="text-gradient">☯ {labels.title[loc]}</span>
                    </h1>
                    <p style={{ color: 'var(--color-text-secondary)' }}>{labels.subtitle[loc]}</p>
                </div>

                <div className="glass-card" style={{ padding: 'var(--space-8)' }}>
                    <div style={{ display: 'grid', gap: 'var(--space-4)' }}>
                        <div className="form-group">
                            <label>{labels.date[loc]}</label>
                            <input type="date" className="input" value={birthDate} onChange={(e) => setBirthDate(e.target.value)} />
                        </div>
                        <div className="form-group">
                            <label>{labels.time[loc]}</label>
                            <input type="time" className="input" value={birthTime} onChange={(e) => setBirthTime(e.target.value)} />
                        </div>

                        {/* 성별 선택 */}
                        <div className="form-group">
                            <label>{labels.genderLabel[loc]}</label>
                            <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                                {(['male', 'female'] as const).map((g) => (
                                    <button
                                        key={g}
                                        className={`btn ${gender === g ? 'btn-primary' : 'btn-secondary'}`}
                                        onClick={() => setGender(g)}
                                        style={{ flex: 1 }}
                                    >
                                        {g === 'male' ? '🧙‍♂️' : '🧙‍♀️'} {labels[g][loc]}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
                            <label style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', cursor: 'pointer' }}>
                                <input type="checkbox" checked={isLunar} onChange={(e) => setIsLunar(e.target.checked)} style={{ accentColor: 'var(--color-accent-primary)' }} />
                                <span style={{ fontSize: 'var(--text-sm)' }}>{labels.lunar[loc]}</span>
                            </label>
                        </div>

                        {/* 질문 입력 */}
                        <div className="form-group">
                            <label>{labels.question[loc]}</label>
                            <textarea
                                className="input"
                                value={question}
                                onChange={(e) => setQuestion(e.target.value)}
                                placeholder={labels.questionPlaceholder[loc]}
                                rows={2}
                                style={{ resize: 'vertical' }}
                            />
                        </div>

                        <button
                            className="btn btn-primary btn-lg"
                            style={{ marginTop: 'var(--space-4)' }}
                            onClick={handleAnalyze}
                            disabled={!birthDate || loading}
                        >
                            {loading ? '⏳...' : labels.analyze[loc]}
                        </button>
                    </div>
                </div>

                {/* 사주팔자 표시 — AI 분석 클릭 후 표시 */}
                {showChart && sajuResult && (
                    <div className="glass-card" style={{ marginTop: 'var(--space-8)', padding: 'var(--space-8)' }}>
                        <h3 style={{ textAlign: 'center', marginBottom: 'var(--space-6)', fontWeight: 700, fontSize: 'var(--text-xl)' }}>
                            {loc === 'ko' ? '사주팔자' : loc === 'ja' ? '四柱八字' : loc === 'zh' ? '四柱八字' : 'Four Pillars'}
                        </h3>
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 'var(--space-4)', textAlign: 'center' }}>
                            {pillarsOrder.map((key) => {
                                const pillar = sajuResult ? sajuResult[key] : null;
                                return (
                                    <div key={key} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
                                        <span style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)', fontWeight: 600 }}>
                                            {pillarLabels[key][loc]}
                                        </span>
                                        {/* 천간 */}
                                        <div style={{
                                            background: 'var(--color-bg-secondary)',
                                            borderRadius: 'var(--radius-md)',
                                            padding: 'var(--space-4)',
                                            border: pillar ? `2px solid ${pillar.stemColor}` : '1px solid var(--color-border)',
                                            transition: 'all 0.4s ease',
                                        }}>
                                            <div style={{
                                                fontSize: 'var(--text-3xl)',
                                                fontWeight: 800,
                                                color: pillar ? pillar.stemColor : 'var(--color-text-muted)',
                                                transition: 'color 0.4s ease',
                                            }}>
                                                {pillar ? `${pillar.stem}` : '—'}
                                            </div>
                                            <div style={{
                                                fontSize: 'var(--text-sm)',
                                                color: pillar ? pillar.stemColor : 'var(--color-text-muted)',
                                                fontWeight: 600, opacity: 0.8,
                                            }}>
                                                {pillar ? pillar.stemHanja : pillarLabels.stem[loc]}
                                            </div>
                                        </div>
                                        {/* 지지 */}
                                        <div style={{
                                            background: 'var(--color-bg-secondary)',
                                            borderRadius: 'var(--radius-md)',
                                            padding: 'var(--space-4)',
                                            border: pillar ? `2px solid ${pillar.branchColor}` : '1px solid var(--color-border)',
                                            transition: 'all 0.4s ease',
                                        }}>
                                            <div style={{
                                                fontSize: 'var(--text-3xl)',
                                                fontWeight: 800,
                                                color: pillar ? pillar.branchColor : 'var(--color-text-muted)',
                                                transition: 'color 0.4s ease',
                                            }}>
                                                {pillar ? `${pillar.branch}` : '—'}
                                            </div>
                                            <div style={{
                                                fontSize: 'var(--text-sm)',
                                                color: pillar ? pillar.branchColor : 'var(--color-text-muted)',
                                                fontWeight: 600, opacity: 0.8,
                                            }}>
                                                {pillar ? pillar.branchHanja : pillarLabels.branch[loc]}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* 오행 분포 — AI 분석 클릭 후 표시 */}
                {showChart && sajuResult && (
                    <div className="glass-card" style={{ marginTop: 'var(--space-6)', padding: 'var(--space-6)' }}>
                        <h3 style={{ textAlign: 'center', marginBottom: 'var(--space-6)', fontWeight: 700, fontSize: 'var(--text-xl)' }}>
                            {loc === 'ko' ? '오행 분포' : loc === 'ja' ? '五行分布' : loc === 'zh' ? '五行分布' : 'Five Elements'}
                        </h3>
                        <div style={{ display: 'flex', justifyContent: 'center', gap: 'var(--space-6)', flexWrap: 'wrap' }}>
                            {elementsList.map((el) => {
                                const count = sajuResult ? sajuResult.elements[el.key] : 0;
                                const pct = sajuResult ? Math.round((count / maxEl) * 100) : 0;
                                return (
                                    <div key={el.key} style={{ textAlign: 'center', minWidth: '70px' }}>
                                        <div style={{ fontSize: 'var(--text-2xl)', marginBottom: 'var(--space-1)' }}>{el.icon}</div>
                                        <div style={{ fontSize: 'var(--text-xs)', color: el.color, fontWeight: 700 }}>
                                            {el.name[loc as keyof typeof el.name] || el.name.en}
                                        </div>
                                        {/* 분포 바 */}
                                        <div style={{
                                            width: '50px', height: '6px',
                                            background: 'var(--color-border)',
                                            borderRadius: '3px',
                                            margin: 'var(--space-1) auto 0',
                                            overflow: 'hidden',
                                        }}>
                                            <div style={{
                                                width: `${pct}%`,
                                                height: '100%',
                                                background: el.color,
                                                borderRadius: '3px',
                                                transition: 'width 0.6s ease',
                                            }} />
                                        </div>
                                        {sajuResult && (
                                            <div style={{
                                                fontSize: 'var(--text-xs)',
                                                color: 'var(--color-text-muted)',
                                                marginTop: '2px',
                                                fontWeight: 600,
                                            }}>
                                                {count}
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* AI 결과 패널 */}
                <FortuneResultPanel
                    system="saju"
                    result={result}
                    loading={loading}
                    error={error}
                    errorCode={errorCode}
                    gender={gender}
                    locale={loc}
                    onRetry={() => handleAnalyze()}
                />
            </div>
        </section>
    );
}

