/**
 * Archmage 전용 2차 검증: OpenAI 결과를 Gemini로 교차 검증
 */
export async function verifyWithGemini(params: {
    system: FortuneSystem;
    locale: Locale;
    originalResult: string;
    question?: string;
    birthDate?: string;
    birthTime?: string;
    birthPlace?: string;
    isLunar?: boolean;
    latitude?: number;
    longitude?: number;
    drawnCards?: { name: string; reversed: boolean }[];
